namespace Nefarius.Utilities.ETW.Relay;

/// <summary>
///     Settings for <see cref="EtwUtil.EnumerateRealtimeRelayFramesAsync" />, which captures a real-time ETW session and
///     produces raw relay frames without decoding anything.
/// </summary>
public sealed class RawEtwRelayProducerOptions
{
    /// <summary>
    ///     The relay session identifier announced in the hello frame. A new value is generated by default. A producer
    ///     that restarts its capture must use a new one.
    /// </summary>
    public Guid SessionId { get; set; } = Guid.NewGuid();

    /// <summary>A free-form description of the producer, carried in the hello frame for diagnostics.</summary>
    public string Producer { get; set; } = "Nefarius.Utilities.ETW realtime";

    /// <summary>
    ///     The largest frame the producer sends, announced in the hello frame. Events whose frame would be larger are
    ///     reported as lost. Default: 1 MiB.
    /// </summary>
    public uint MaxFrameLength { get; set; } = 1024 * 1024;

    /// <summary>Whether frames carry a CRC32C. Default: <see langword="true" />.</summary>
    public bool WithCrc { get; set; } = true;

    internal void Validate()
    {
        ArgumentNullException.ThrowIfNull(Producer);
        ArgumentOutOfRangeException.ThrowIfLessThan(MaxFrameLength, (uint)RawEtwFrameCodec.PrefixLength + 1);
        ArgumentOutOfRangeException.ThrowIfGreaterThan(MaxFrameLength, (uint)RawEtwRelayLimits.AbsoluteMaxFrameLength);
    }
}
